}

/// A single message in a thread (user prompt or AI response)
struct ThreadMessage: Codable, Identifiable {
    let id: UUID
    let role: MessageRole
    let content: String
    let createdAt: Date

    init(
        id: UUID = UUID(),
        role: MessageRole,
        content: String,
        createdAt: Date = Date()
    ) {
        self.id = id
        self.role = role
        self.content = content
        self.createdAt = createdAt
    }
}

enum MessageRole: String, Codable {
    case user
    case assistant
}

/// A bookmark for quick navigation to a specific location in a book
struct Bookmark: Codable, Identifiable {
    let id: UUID
    let chapterId: String
    let chapterIndex: Int
    let chapterTitle: String
    let note: String?
    let scrollPosition: Double  // 0.0 to 1.0 representing position in chapter
    let createdAt: Date

    init(
        id: UUID = UUID(),
        chapterId: String,
        chapterIndex: Int,
        chapterTitle: String,
        note: String? = nil,
        scrollPosition: Double = 0.0,
        createdAt: Date = Date()
    ) {
        self.id = id
        self.chapterId = chapterId
        self.chapterIndex = chapterIndex
        self.chapterTitle = chapterTitle
        self.note = note
        self.scrollPosition = scrollPosition
        self.createdAt = createdAt
    }
}

