                    Spacer()

                    // Count badge
                    Text("\(count)")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .padding(.horizontal, 8)
                        .padding(.vertical, 2)
                        .background(.quaternary)
                        .cornerRadius(10)
                }
            }
        }
        .buttonStyle(.plain)
    }
