    // MARK: - Public Methods

    /// Start speaking the given text
    @MainActor
    func speak(text: String) {
        guard !text.isEmpty else { return }

        currentText = text

        // Cancel any existing speech
        stop()

        // Start new speech task
        speakingTask = Task {
            await performSpeak(text: text)
        }

