// MARK: - Voice Selection View

struct VoiceSelectionView: View {
    @Bindable var ttsService: TextToSpeechService

    @State private var selectedLanguage: String = "en"
    @State private var voicesByLanguage: [String: [AVSpeechSynthesisVoice]] = [:]

    var body: some View {
        VStack(spacing: 0) {
            // Header
            VStack(alignment: .leading, spacing: 8) {
                HStack {
                    Image(systemName: "person.wave.2.fill")
                        .font(.title2)
                        .foregroundStyle(.blue)

                    Text("Select Voice")
                        .font(.headline)

                    Spacer()
                }

                Text("Choose a voice for reading")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
            .padding()

            Divider()

            // Language Picker
            if voicesByLanguage.count > 1 {
                Picker("Language", selection: $selectedLanguage) {
                    ForEach(Array(voicesByLanguage.keys.sorted()), id: \.self) { langCode in
                        Text(TextToSpeechService.languageName(for: langCode))
                            .tag(langCode)
                    }
                }
                .pickerStyle(.segmented)
                .padding(.horizontal)
                .padding(.top, 8)
            }

            // Voice List
            ScrollView {
                VStack(alignment: .leading, spacing: 4) {
                    if let voices = voicesByLanguage[selectedLanguage] {
                        ForEach(voices, id: \.identifier) { voice in
                            VoiceRow(
                                voice: voice,
                                isSelected: ttsService.selectedVoice?.identifier == voice.identifier
                            ) {
                                ttsService.selectedVoice = voice
                            }
                        }
                    } else {
                        ContentUnavailableView(
                            "No Voices Available",
                            systemImage: "person.slash",
                            description: Text("No voices found for this language")
                        )
                    }
                }
                .padding(.horizontal)
                .padding(.vertical, 8)
            }
        }
        .onAppear {
            voicesByLanguage = TextToSpeechService.voicesByLanguage()

            // Set initial language from current voice
            if let currentVoice = ttsService.selectedVoice {
                selectedLanguage = String(currentVoice.language.prefix(2))
            }
        }
    }
}

