extension AppError {
    static func ttsInitializationFailed(_ message: String) -> AppError {
        .customError(message: "Failed to initialize TTS: \(message)", severity: .error)
    }

    static func ttsSynthesisFailed(_ message: String) -> AppError {
        .customError(message: "TTS synthesis failed: \(message)", severity: .error)
    }
}

